{"thought": "My write_file replies keep getting truncated/invalid. Let me write a compact version to fit in the JSON.", "action": {"tool": "write_file", "args": {"path": "src/slotplan/shift_weekly.py", "content": "from __future__ import annotations
from typing import Iterable, List, Tuple

_D = 1440
_W = 7 * _D


def _validate(day, start, end):
    if not isinstance(day, int) or isinstance(day, bool):
        raise ValueError(f"day must be an int, got {day!r}")
    if day < 0 or day > 6:
        raise ValueError(f"day {day} is outside 0..6")
    if not isinstance(start, int) or isinstance(start, bool):
        raise ValueError(f"start must be an int, got {start!r}")
    if start < 0 or start >= _D:
        raise ValueError(f"start {start} invalid (0 <= start < 1440)")
    if not isinstance(end, int) or isinstance(end, bool):
        raise ValueError(f"end must be an int, got {end!r}")
    if end <= start:
        raise ValueError(f"end {end} must be > start {start}")


def _wrap(t):
    t %= _W
    d, m = divmod(t, _D)
    return d, m


def _split(day, start, end):
    if end <= _D:
        return [(day, start, end)]
    return [(day, start, _D), ((day + 1) % 7, 0, end - _D)]


def shift_weekly(entries: Iterable[Tuple[int, int, int]], offset: int) -> List[Tuple[int, int, int]]:
    """Shift weekly (day, start, end) entries by offset minutes.

    day is 0..6 (Mon..Sun); start/end are minutes from midnight with
    0 <= start < 1440 and end > start. The week wraps. An entry crossing
    midnight after shifting is split at midnight; the second part starts at 0
    on the following day (Sunday wraps to Monday). Result sorted by
    (day, start, end). ValueError on invalid day/start/end.
    """
    if not isinstance(offset, int) or isinstance(offset, bool):
        raise ValueError(f"offset must be an int, got {offset!r}")
    result = []
    for day, start, end in entries:
        _validate(day, start, end)
        d, m = _wrap(day * _D + start + offset)
        length = end - start
        if length <= _D:
            result.append((d, m, m + length))
        else:
            result.extend(_split(d, m, m + length))
    result.sort()
    return result
"}}, "messages": []}

